import { jsPDF } from "jspdf";

/**
 * Service to export AI Project Blueprints to executive, publication-ready PDFs using jsPDF.
 */
export const pdfExportService = {
  /**
   * Generates and downloads a multi-page PDF blueprint.
   * @param {Object} blueprint The blueprint object generated by aiBlueprintService
   */
  exportBlueprintToPdf(blueprint) {
    if (!blueprint) {
      throw new Error("No blueprint data provided for PDF export");
    }

    const doc = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a4",
    });

    const pageWidth = 210;
    const pageHeight = 297;
    const margin = 16;
    const usableWidth = pageWidth - margin * 2;
    let y = margin;

    // Brand Colors
    const primaryColor = [15, 23, 42]; // #0f172a slate-900
    const accentColor = [255, 107, 0]; // #ff6b00 brand orange
    const secondaryColor = [79, 70, 229]; // #4f46e5 indigo-600
    const textDark = [30, 41, 59]; // #1e293b
    const textMuted = [100, 116, 139]; // #64748b
    const bgLight = [248, 250, 252]; // #f8fafc
    const borderColor = [226, 232, 240]; // #e2e8f0

    const checkPage = (requiredSpace = 20) => {
      if (y + requiredSpace > pageHeight - margin) {
        doc.addPage();
        y = margin + 10;
        drawRunningHeader();
      }
    };

    const drawRunningHeader = () => {
      doc.setFont("helvetica", "normal");
      doc.setFontSize(8);
      doc.setTextColor(textMuted[0], textMuted[1], textMuted[2]);
      doc.text("FREELANCEHUB AI ARCHITECT • PROJECT BLUEPRINT", margin, margin);
      const titleShort = (blueprint.title || "Project Blueprint").substring(0, 45);
      doc.text(titleShort, pageWidth - margin, margin, { align: "right" });
      doc.setDrawColor(borderColor[0], borderColor[1], borderColor[2]);
      doc.setLineWidth(0.3);
      doc.line(margin, margin + 2, pageWidth - margin, margin + 2);
    };

    const drawSectionHeader = (number, title) => {
      checkPage(18);
      y += 4;
      doc.setFillColor(bgLight[0], bgLight[1], bgLight[2]);
      doc.roundedRect(margin, y, usableWidth, 9, 1.5, 1.5, "F");

      doc.setFillColor(accentColor[0], accentColor[1], accentColor[2]);
      doc.rect(margin, y, 3, 9, "F");

      doc.setFont("helvetica", "bold");
      doc.setFontSize(11);
      doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
      doc.text(`${number}. ${title.toUpperCase()}`, margin + 6, y + 6.2);
      y += 13;
    };

    // -------------------------------------------------------------------
    // 1. COVER / HEADER BANNER
    // -------------------------------------------------------------------
    // Header Background Card
    doc.setFillColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.roundedRect(margin, y, usableWidth, 42, 3, 3, "F");

    // Decorative Accent Line
    doc.setFillColor(accentColor[0], accentColor[1], accentColor[2]);
    doc.rect(margin, y + 40, usableWidth, 2, "F");

    // Brand Tag
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(accentColor[0], accentColor[1], accentColor[2]);
    doc.text("⚡ FREELANCEHUB ARCHITECT STUDIO", margin + 8, y + 9);

    // Title
    doc.setFont("helvetica", "bold");
    doc.setFontSize(18);
    doc.setTextColor(255, 255, 255);
    const titleLines = doc.splitTextToSize(blueprint.title || "Untitled Project", usableWidth - 16);
    doc.text(titleLines.slice(0, 2), margin + 8, y + 18);

    // Tagline / Category
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(203, 213, 225);
    const subtitle = blueprint.tagline || blueprint.category || "Full-Stack System Blueprint";
    doc.text(doc.splitTextToSize(subtitle, usableWidth - 16)[0], margin + 8, y + 27);

    // Metadata line (Date, Version, Engine)
    doc.setFontSize(8);
    doc.setTextColor(148, 163, 184);
    const dateStr = new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
    doc.text(`Engine: Gemini 3.8 Flash  •  Date: ${dateStr}  •  Status: Production Architecture Specification`, margin + 8, y + 35);

    y += 48;

    // -------------------------------------------------------------------
    // 2. EXECUTIVE OVERVIEW & SCOPE
    // -------------------------------------------------------------------
    drawSectionHeader("1", "Executive Overview & Problem Scope");

    // Metadata Badges Row
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(textDark[0], textDark[1], textDark[2]);

    const badges = [
      { label: "Category", val: blueprint.category || "Software Engineering" },
      { label: "Architecture", val: blueprint.systemArchitecture?.pattern || "Modular Full-Stack" },
      { label: "Timeline", val: blueprint.estimatedDuration || "4-6 Weeks" },
    ];

    const badgeWidth = (usableWidth - 6) / 3;
    badges.forEach((b, i) => {
      const bx = margin + i * (badgeWidth + 3);
      doc.setFillColor(bgLight[0], bgLight[1], bgLight[2]);
      doc.setDrawColor(borderColor[0], borderColor[1], borderColor[2]);
      doc.roundedRect(bx, y, badgeWidth, 14, 1.5, 1.5, "FD");

      doc.setFont("helvetica", "normal");
      doc.setFontSize(7.5);
      doc.setTextColor(textMuted[0], textMuted[1], textMuted[2]);
      doc.text(b.label.toUpperCase(), bx + 4, y + 4.5);

      doc.setFont("helvetica", "bold");
      doc.setFontSize(9);
      doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
      doc.text(b.val, bx + 4, y + 10.5);
    });
    y += 18;

    if (blueprint.summary) {
      doc.setFont("helvetica", "bold");
      doc.setFontSize(10);
      doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
      doc.text("Executive Summary:", margin, y);
      y += 5;

      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      doc.setTextColor(textDark[0], textDark[1], textDark[2]);
      const summaryLines = doc.splitTextToSize(blueprint.summary, usableWidth);
      doc.text(summaryLines, margin, y);
      y += summaryLines.length * 4.2 + 4;
    }

    if (blueprint.problemStatement || blueprint.solution) {
      checkPage(25);
      if (blueprint.problemStatement) {
        doc.setFont("helvetica", "bold");
        doc.setFontSize(9.5);
        doc.setTextColor(accentColor[0], accentColor[1], accentColor[2]);
        doc.text("Challenge / Problem Statement:", margin, y);
        y += 4.5;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(8.5);
        doc.setTextColor(textDark[0], textDark[1], textDark[2]);
        const pLines = doc.splitTextToSize(blueprint.problemStatement, usableWidth);
        doc.text(pLines, margin, y);
        y += pLines.length * 4 + 3;
      }

      if (blueprint.solution) {
        checkPage(20);
        doc.setFont("helvetica", "bold");
        doc.setFontSize(9.5);
        doc.setTextColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
        doc.text("Engineered Solution:", margin, y);
        y += 4.5;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(8.5);
        doc.setTextColor(textDark[0], textDark[1], textDark[2]);
        const sLines = doc.splitTextToSize(blueprint.solution, usableWidth);
        doc.text(sLines, margin, y);
        y += sLines.length * 4 + 4;
      }
    }

    // -------------------------------------------------------------------
    // 3. TECHNOLOGY STACK SPECIFICATION
    // -------------------------------------------------------------------
    if (blueprint.techStack) {
      drawSectionHeader("2", "Recommended Technology Stack");

      const techCategories = [
        { name: "Frontend Client", items: blueprint.techStack.frontend },
        { name: "Backend & Runtime", items: blueprint.techStack.backend },
        { name: "Databases & Storage", items: blueprint.techStack.database },
        { name: "Cloud & DevOps", items: blueprint.techStack.devops },
        { name: "Third-Party & APIs", items: blueprint.techStack.apis },
      ].filter((tc) => tc.items && tc.items.length > 0);

      techCategories.forEach((tc) => {
        checkPage(12);
        doc.setFont("helvetica", "bold");
        doc.setFontSize(9);
        doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
        doc.text(`• ${tc.name}:`, margin + 2, y);

        doc.setFont("helvetica", "normal");
        doc.setFontSize(8.5);
        doc.setTextColor(textDark[0], textDark[1], textDark[2]);
        const itemsStr = Array.isArray(tc.items) ? tc.items.join("   |   ") : String(tc.items);
        const splitItems = doc.splitTextToSize(itemsStr, usableWidth - 45);
        doc.text(splitItems, margin + 45, y);
        y += Math.max(splitItems.length * 4.2, 5.5);
      });
      y += 4;
    }

    // -------------------------------------------------------------------
    // 4. SYSTEM ARCHITECTURE & DESIGN
    // -------------------------------------------------------------------
    if (blueprint.systemArchitecture) {
      drawSectionHeader("3", "System Design & Multi-Tier Architecture");

      if (blueprint.systemArchitecture.summary) {
        doc.setFont("helvetica", "normal");
        doc.setFontSize(9);
        doc.setTextColor(textDark[0], textDark[1], textDark[2]);
        const archSummary = doc.splitTextToSize(blueprint.systemArchitecture.summary, usableWidth);
        doc.text(archSummary, margin, y);
        y += archSummary.length * 4.2 + 5;
      }

      // Architecture Tiers
      if (Array.isArray(blueprint.systemArchitecture.tiers)) {
        blueprint.systemArchitecture.tiers.forEach((tier) => {
          checkPage(24);
          doc.setFillColor(bgLight[0], bgLight[1], bgLight[2]);
          doc.setDrawColor(borderColor[0], borderColor[1], borderColor[2]);
          doc.roundedRect(margin, y, usableWidth, 18, 1.5, 1.5, "FD");

          doc.setFont("helvetica", "bold");
          doc.setFontSize(9);
          doc.setTextColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
          doc.text(`[${tier.name || "Tier"}]`, margin + 4, y + 5);

          if (tier.technologies) {
            doc.setFont("helvetica", "normal");
            doc.setFontSize(8);
            doc.setTextColor(textMuted[0], textMuted[1], textMuted[2]);
            const techTxt = Array.isArray(tier.technologies) ? tier.technologies.join(", ") : tier.technologies;
            doc.text(`Tech: ${techTxt}`, margin + 50, y + 5);
          }

          doc.setFont("helvetica", "normal");
          doc.setFontSize(8.5);
          doc.setTextColor(textDark[0], textDark[1], textDark[2]);
          const descLines = doc.splitTextToSize(tier.responsibilities || tier.description || "", usableWidth - 8);
          doc.text(descLines.slice(0, 2), margin + 4, y + 10.5);
          y += 21;
        });
      }

      // Visual / Text Diagram representation
      if (blueprint.systemArchitecture.diagramSummary) {
        checkPage(25);
        doc.setFont("helvetica", "bold");
        doc.setFontSize(9);
        doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
        doc.text("System Flow Topology:", margin, y);
        y += 4;

        doc.setFillColor(15, 23, 42); // dark slate block for terminal feel
        doc.roundedRect(margin, y, usableWidth, 22, 1.5, 1.5, "F");

        doc.setFont("courier", "normal");
        doc.setFontSize(7.5);
        doc.setTextColor(56, 189, 248); // sky-400
        const diagLines = doc.splitTextToSize(blueprint.systemArchitecture.diagramSummary, usableWidth - 8);
        doc.text(diagLines.slice(0, 4), margin + 4, y + 5);
        y += 26;
      }
    }

    // -------------------------------------------------------------------
    // 5. USER JOURNEY & EVENT DATA FLOW
    // -------------------------------------------------------------------
    if (Array.isArray(blueprint.userFlow) && blueprint.userFlow.length > 0) {
      drawSectionHeader("4", "End-to-End User & Request Flow");

      blueprint.userFlow.forEach((step, idx) => {
        checkPage(18);
        const stepNum = step.stepNumber || idx + 1;
        doc.setFillColor(accentColor[0], accentColor[1], accentColor[2]);
        doc.circle(margin + 3.5, y + 2, 2.8, "F");

        doc.setFont("helvetica", "bold");
        doc.setFontSize(7.5);
        doc.setTextColor(255, 255, 255);
        doc.text(String(stepNum), margin + 3.5, y + 3, { align: "center" });

        doc.setFont("helvetica", "bold");
        doc.setFontSize(9);
        doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
        doc.text(`${step.stepName || step.name || "Flow Step"}`, margin + 10, y + 3);

        if (step.actor) {
          doc.setFont("helvetica", "normal");
          doc.setFontSize(7.5);
          doc.setTextColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
          doc.text(`[Actor: ${step.actor}]`, pageWidth - margin, y + 3, { align: "right" });
        }

        y += 6;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(8);
        doc.setTextColor(textDark[0], textDark[1], textDark[2]);
        const actionTxt = `Action: ${step.action || ""}`;
        const respTxt = step.systemResponse ? ` | System: ${step.systemResponse}` : "";
        const stepCombined = doc.splitTextToSize(`${actionTxt}${respTxt}`, usableWidth - 10);
        doc.text(stepCombined, margin + 10, y);
        y += stepCombined.length * 3.8 + 4;
      });
      y += 2;
    }

    // -------------------------------------------------------------------
    // 6. CODEBASE & DIRECTORY STRUCTURE
    // -------------------------------------------------------------------
    if (Array.isArray(blueprint.directoryStructure) && blueprint.directoryStructure.length > 0) {
      drawSectionHeader("5", "Project Directory & Codebase Structure");

      doc.setFillColor(241, 245, 249);
      doc.setDrawColor(borderColor[0], borderColor[1], borderColor[2]);
      const dirBoxHeight = Math.min(blueprint.directoryStructure.length * 5 + 6, 90);
      checkPage(dirBoxHeight + 8);

      doc.roundedRect(margin, y, usableWidth, dirBoxHeight, 1.5, 1.5, "FD");

      let treeY = y + 5;
      blueprint.directoryStructure.slice(0, 16).forEach((item) => {
        const isDir = item.type === "dir" || item.path?.endsWith("/");
        doc.setFont("courier", isDir ? "bold" : "normal");
        doc.setFontSize(8);
        doc.setTextColor(isDir ? secondaryColor[0] : primaryColor[0], isDir ? secondaryColor[1] : primaryColor[1], isDir ? secondaryColor[2] : primaryColor[2]);

        const prefix = isDir ? "📁 " : "📄 ";
        doc.text(`${prefix}${item.path}`, margin + 4, treeY);

        if (item.description) {
          doc.setFont("helvetica", "normal");
          doc.setFontSize(7.5);
          doc.setTextColor(textMuted[0], textMuted[1], textMuted[2]);
          const descClean = String(item.description).substring(0, 50);
          doc.text(`— ${descClean}`, margin + 70, treeY);
        }

        treeY += 5;
      });
      y += dirBoxHeight + 6;
    }

    // -------------------------------------------------------------------
    // 7. DATABASE SCHEMA & ENTITY MODELS
    // -------------------------------------------------------------------
    if (Array.isArray(blueprint.databaseSchema) && blueprint.databaseSchema.length > 0) {
      drawSectionHeader("6", "Database Schema & Entity Specifications");

      blueprint.databaseSchema.forEach((table) => {
        const colCount = table.columns ? table.columns.length : 0;
        const estimatedTableSpace = 12 + colCount * 5;
        checkPage(Math.min(estimatedTableSpace, 45));

        doc.setFillColor(bgLight[0], bgLight[1], bgLight[2]);
        doc.setDrawColor(borderColor[0], borderColor[1], borderColor[2]);
        doc.roundedRect(margin, y, usableWidth, 7, 1, 1, "FD");

        doc.setFont("helvetica", "bold");
        doc.setFontSize(9);
        doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
        doc.text(`Table: ${table.tableName || "table_name"}`, margin + 3, y + 4.8);

        if (table.description) {
          doc.setFont("helvetica", "normal");
          doc.setFontSize(7.5);
          doc.setTextColor(textMuted[0], textMuted[1], textMuted[2]);
          doc.text(`(${table.description})`, margin + 55, y + 4.8);
        }
        y += 8;

        if (Array.isArray(table.columns)) {
          // Table Header
          doc.setFont("helvetica", "bold");
          doc.setFontSize(7.5);
          doc.setTextColor(textMuted[0], textMuted[1], textMuted[2]);
          doc.text("COLUMN", margin + 4, y + 3);
          doc.text("DATA TYPE", margin + 50, y + 3);
          doc.text("CONSTRAINTS", margin + 90, y + 3);
          doc.text("PURPOSE", margin + 130, y + 3);
          y += 4.5;

          table.columns.forEach((col) => {
            checkPage(6);
            doc.setFont("courier", "bold");
            doc.setFontSize(7.5);
            doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
            doc.text(col.name, margin + 4, y + 3);

            doc.setFont("courier", "normal");
            doc.setTextColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
            doc.text(col.type || "VARCHAR", margin + 50, y + 3);

            doc.setFont("helvetica", "normal");
            doc.setFontSize(7);
            doc.setTextColor(textMuted[0], textMuted[1], textMuted[2]);
            doc.text(col.constraints || "—", margin + 90, y + 3);
            doc.text(String(col.description || "").substring(0, 30), margin + 130, y + 3);

            y += 4.5;
          });
        }
        y += 4;
      });
    }

    // -------------------------------------------------------------------
    // 8. KEY API ENDPOINTS SPECIFICATION
    // -------------------------------------------------------------------
    if (Array.isArray(blueprint.apiEndpoints) && blueprint.apiEndpoints.length > 0) {
      drawSectionHeader("7", "REST / GraphQL API Endpoints");

      blueprint.apiEndpoints.forEach((api) => {
        checkPage(14);
        const method = (api.method || "GET").toUpperCase();
        let methodColor = secondaryColor;
        if (method === "GET") methodColor = [16, 185, 129]; // green
        if (method === "POST") methodColor = [59, 130, 246]; // blue
        if (method === "PUT" || method === "PATCH") methodColor = [245, 158, 11]; // amber
        if (method === "DELETE") methodColor = [239, 68, 68]; // red

        doc.setFillColor(methodColor[0], methodColor[1], methodColor[2]);
        doc.roundedRect(margin, y, 14, 5, 1, 1, "F");

        doc.setFont("helvetica", "bold");
        doc.setFontSize(6.5);
        doc.setTextColor(255, 255, 255);
        doc.text(method, margin + 7, y + 3.5, { align: "center" });

        doc.setFont("courier", "bold");
        doc.setFontSize(8.5);
        doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
        doc.text(api.path || "/api/v1/resource", margin + 18, y + 3.8);

        y += 6.5;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(8);
        doc.setTextColor(textDark[0], textDark[1], textDark[2]);
        const apiDesc = doc.splitTextToSize(api.description || "Endpoint operation", usableWidth - 6);
        doc.text(apiDesc, margin + 4, y);
        y += apiDesc.length * 3.8 + 2.5;
      });
      y += 2;
    }

    // -------------------------------------------------------------------
    // 9. IMPLEMENTATION MILESTONES & ROADMAP
    // -------------------------------------------------------------------
    if (Array.isArray(blueprint.milestones) && blueprint.milestones.length > 0) {
      drawSectionHeader("8", "Implementation Sprints & Milestones");

      blueprint.milestones.forEach((m) => {
        checkPage(24);
        doc.setFillColor(bgLight[0], bgLight[1], bgLight[2]);
        doc.setDrawColor(borderColor[0], borderColor[1], borderColor[2]);
        doc.roundedRect(margin, y, usableWidth, 18, 1.5, 1.5, "FD");

        doc.setFont("helvetica", "bold");
        doc.setFontSize(9);
        doc.setTextColor(accentColor[0], accentColor[1], accentColor[2]);
        doc.text(`${m.phase || "Sprint"}: ${m.title || "Core Milestones"}`, margin + 4, y + 5);

        if (m.timeline) {
          doc.setFont("helvetica", "normal");
          doc.setFontSize(8);
          doc.setTextColor(textMuted[0], textMuted[1], textMuted[2]);
          doc.text(`Duration: ${m.timeline}`, pageWidth - margin - 4, y + 5, { align: "right" });
        }

        if (Array.isArray(m.deliverables)) {
          doc.setFont("helvetica", "normal");
          doc.setFontSize(7.5);
          doc.setTextColor(textDark[0], textDark[1], textDark[2]);
          const delivStr = m.deliverables.map((d) => `✔ ${d}`).join("   •   ");
          const splitDeliv = doc.splitTextToSize(delivStr, usableWidth - 8);
          doc.text(splitDeliv.slice(0, 2), margin + 4, y + 10.5);
        }
        y += 21;
      });
      y += 2;
    }

    // -------------------------------------------------------------------
    // 10. TEAM & TALENT MATCHING
    // -------------------------------------------------------------------
    if (Array.isArray(blueprint.teamRecommendations) && blueprint.teamRecommendations.length > 0) {
      drawSectionHeader("9", "Recommended Freelance Team Composition");

      blueprint.teamRecommendations.forEach((role) => {
        checkPage(16);
        doc.setFont("helvetica", "bold");
        doc.setFontSize(9);
        doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
        doc.text(`• ${role.role || "Senior Engineer"} (${role.count || 1}x)`, margin + 2, y);

        if (role.estimatedHours) {
          doc.setFont("helvetica", "normal");
          doc.setFontSize(8);
          doc.setTextColor(textMuted[0], textMuted[1], textMuted[2]);
          doc.text(`Est: ${role.estimatedHours}`, pageWidth - margin, y, { align: "right" });
        }

        y += 4.5;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(8);
        doc.setTextColor(textDark[0], textDark[1], textDark[2]);
        const skillsText = Array.isArray(role.skills) ? role.skills.join(", ") : role.skills;
        const roleDesc = `${role.responsibilities || "Key development responsibilities"} (Skills: ${skillsText || "Full-stack"})`;
        const splitRole = doc.splitTextToSize(roleDesc, usableWidth - 6);
        doc.text(splitRole, margin + 4, y);
        y += splitRole.length * 3.8 + 3.5;
      });
    }

    // -------------------------------------------------------------------
    // RUNNING FOOTERS ON ALL PAGES
    // -------------------------------------------------------------------
    const totalPages = doc.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      doc.setDrawColor(borderColor[0], borderColor[1], borderColor[2]);
      doc.setLineWidth(0.3);
      doc.line(margin, pageHeight - margin + 3, pageWidth - margin, pageHeight - margin + 3);

      doc.setFont("helvetica", "normal");
      doc.setFontSize(8);
      doc.setTextColor(textMuted[0], textMuted[1], textMuted[2]);
      doc.text("FreelanceHub • High-Performance Project Architecture", margin, pageHeight - margin + 8);
      doc.text(`Page ${i} of ${totalPages}`, pageWidth - margin, pageHeight - margin + 8, { align: "right" });
    }

    // Save / Output PDF
    const filename = `${(blueprint.title || "project")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "")}-blueprint.pdf`;

    if (typeof window !== "undefined" && typeof document !== "undefined") {
      doc.save(filename);
    } else {
      // In server or test environments, generate output buffer
      doc.output("arraybuffer");
    }

    return filename;
  },
};
